const KEY='reels-start-v1';
let progressKey=KEY;
let storageUnavailable=false;
function readState(){try{return KadrState.normalize(JSON.parse(localStorage.getItem(progressKey)))}catch{storageUnavailable=true;return KadrState.normalize({})}}
let state=readState(),saved=structuredClone(state),current='home',toastTimer;
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{let raw;try{raw=JSON.parse(localStorage.getItem(progressKey))}catch{raw=null}const remote=KadrState.normalize(raw);state=KadrState.merge(saved,state,remote);localStorage.setItem(progressKey,JSON.stringify(state));saved=structuredClone(state);storageUnavailable=false;window.KadrCloud?.changed();return true}catch{toast('Не удалось сохранить на устройстве. Скачай карточку ответов.');storageUnavailable=true;return false}}
function toast(t){const e=document.querySelector('#toast');clearTimeout(toastTimer);e.textContent=t;e.classList.add('show');toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
const missions=[['Выбери свой аккаунт','Найди точку, с которой начнёшь.','АККАУНТ'],['Проверь его состояние','Узнай исходные условия.','ДИАГНОСТИКА'],['Собери настройки','Пройди экраны по образцу.','НАСТРОЙКИ'],['Реши, что оставить','Разберись со старыми публикациями.','ПРОФИЛЬ'],['Дай причину остаться','Собери имя и описание блога.','ОФОРМЛЕНИЕ'],['Сохрани точку старта','Зафиксируй данные для сравнения.','СТАРТ']];
const field=(key,label,placeholder='',type='text')=>`<label class="field">${label}<input data-field="${key}" type="${type}" ${type==='number'?'min="0" step="1"':''} value="${esc(state.fields[key])}" placeholder="${placeholder}"></label>`;
const area=(key,label,placeholder='')=>`<label class="field">${label}<textarea data-field="${key}" placeholder="${placeholder}">${esc(state.fields[key])}</textarea></label>`;
const select=(key,label,options)=>`<label class="field">${label}<select data-field="${key}" aria-label="${label}"><option value="">Выбери вариант</option>${options.map(o=>`<option ${state.fields[key]===o?'selected':''}>${o}</option>`).join('')}</select></label>`;
const detail=(title,body)=>`<details><summary>${title}</summary><p>${body}</p></details>`;
const check=(key,text)=>`<label class="check"><input type="checkbox" data-field="${key}" ${state.fields[key]?'checked':''}>${text}</label>`;
const block=(title,body)=>`<section class="content-block"><h3>${title}</h3>${body}</section>`;
const practiceBlock = body => '<section id="lesson-practice" class="content-block practice-block" tabindex="-1"><h3>Твоя практика</h3>' + body + '</section>';
const prompt=()=>`Помоги оформить мой блог. Имя: ${state.fields.name||'[имя]'}. Темы: ${state.fields.topics||'[темы]'}. Формат: ${state.fields.format||'[с лицом / без лица]'}. Подача: ${state.fields.tone||'[манера общения]'}.\nПредложи три варианта поля имени и три описания до 150 символов с пробелами каждое. Сделай понятным, какой контент получит подписчик. Не придумывай квалификацию, достижения и результаты. Не представляй меня экспертом без оснований. Пиши естественно, без пафоса. Добавь простой призыв подписаться. Я отдельно проверю длину готового текста.`;
const paths={map:'M4 6l5-2 6 2 5-2v14l-5 2-6-2-5 2V6zm5-2v14m6-12v14',bag:'M5 8h14l1 12H4L5 8zm4 0V6a3 3 0 016 0v2',award:'M8 3h8l3 6-7 5-7-5 3-6zm1 10-2 8 5-3 5 3-2-8',user:'M16 7a4 4 0 11-8 0 4 4 0 018 0zM4 21v-2a8 8 0 0116 0v2',star:'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z',check:'M5 12l4 4L19 6',play:'M8 4l12 8-12 8V4z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zm-4 9 3 3 5-6',sliders:'M5 4v16M12 4v16M19 4v16M2 9h6m1 7h6m1-9h6',archive:'M4 8h16v12H4V8zm-1-5h18v5H3V3zm6 9h6',pen:'M4 20l1-6L16 3l5 5-11 11-6 1zm9-14 5 5',flag:'M5 21V3m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',lock:'M6 10h12v11H6V10zm3 0V6a3 3 0 016 0v4',bolt:'M13 2L4 14h7l-1 8 10-13h-7l0-7',chevron:'M9 5l7 7-7 7',book:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2V4zm9 2v15',calendar:'M4 5h16v16H4V5zm3-3v6m10-6v6M4 11h16',sound:'M4 9h4l5-5v16l-5-5H4V9zm12-2q6 5 0 10',close:'M6 6l12 12M18 6 6 18',more:'M4 12h2m5 0h2m5 0h2',list:'M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1',grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const dayKey=()=>KadrState.dateKey();
const todayCount=()=>state.activity[dayKey()]||0;
const rank=()=>state.done.length>=42?'Автор со своей системой':state.done.length>=24?'Создатель контента':state.done.length>=6?'Исследователь':'Начинающий автор';
const navs = [
  ['home', 'map', 'Путь обучения', 'Путь'],
  ['materials', 'bag', 'Рюкзак', 'Рюкзак'],
  ['calendar', 'calendar', 'Календарь', 'Календарь'],
  ['preflight', 'sliders', 'Проверка ролика'],
  ['achievements', 'award', 'Награды'],
  ['help', 'book', 'Центр помощи'],
  ['profile', 'user', 'Профиль']
];
const navButton = ([view, glyph, label, short], active, mobile = false) =>
  `<button type="button" data-view="${view}" class="${active === view ? 'active' : ''}" ${active === view ? 'aria-current="page"' : ''}>${icon(glyph)}<span>${mobile ? short || label : label}</span></button>`;

function navRender() {
  const view = typeof current === 'number' || String(current).startsWith('chapter/') ? 'home' : current;
  const group = (name, entries) => `<div class="rail-group"><span class="rail-label">${name}</span>${entries.map(link => navButton(link, view)).join('')}</div>`;
  document.querySelector('#mainNav').innerHTML = group('Моя студия', navs.slice(0, 3)) + group('Инструменты', navs.slice(3, 6));
  const moreActive = navs.slice(3).some(([v]) => v === view);
  document.querySelector('#mobileNav').innerHTML = navs.slice(0, 3).map(link => navButton(link, view, true)).join('') +
    `<button type="button" id="moreNav" class="${moreActive ? 'active' : ''}" aria-haspopup="dialog">${icon('more')}<span>Ещё</span></button>`;
  document.querySelector('#xpStat').innerHTML = icon('bolt') + `<b>${state.done.length * 50} XP</b>`;
  const avatar = document.querySelector('.avatar-button');
  avatar.innerHTML = state.fields.displayName?.trim?.() ? esc(Array.from(state.fields.displayName.trim())[0].toLocaleUpperCase('ru')) : icon('user');
  const count = state.done.length;
  document.querySelector('#railProgress').innerHTML = `<div><span>Прогресс курса</span><b>${Math.round(count / missions.length * 100)}%</b></div>
    <progress max="${missions.length}" value="${count}" aria-label="Завершено миссий"></progress><small>${count} из ${missions.length} миссий</small>`;
}

function showMobileNav() {
  document.querySelector('#rewardContent').innerHTML = `<button type="button" id="closeReward" class="modal-close" aria-label="Закрыть">${icon('close')}</button><h2>Разделы студии</h2><div class="more-menu">${navs.slice(3).map(link => navButton(link, current)).join('')}</div>`;
  openDialog('reward');
}

function lessonHeader(i, intro) {
  const c = Math.floor(i / 6), j = i % 6;
  return `<button class="back" data-view="chapter/${c+1}">${icon('map')} К главе «${chapters[c].title}»</button>
    <header class="lesson-heading"><div><span class="folio">Глава ${c+1} из 7 <i></i> Миссия ${j+1} из 6</span><h1>${missions[i][0]}</h1><p class="lead">${intro}</p></div>
    <img class="lesson-stamp" src="assets/stickers/${chapterStickers[c]}.svg" alt="" width="140" height="140"></header>
    <nav class="step-strip" aria-label="Миссии главы">${chapterIds(c).map((id,k) => `<button data-lesson="${id}" class="${id === i ? 'current' : ''} ${state.done.includes(id) ? 'finished' : ''}" ${id === i ? 'aria-current="step"' : ''} aria-label="Миссия ${k+1}. ${esc(missions[id][0])}${state.done.includes(id) ? ', пройдена' : ''}"><span>${state.done.includes(id) ? icon('check') : String(k+1).padStart(2,'0')}</span><i>${missions[id][2].toLocaleLowerCase('ru')}</i></button>`).join('')}</nav>`;
}

function jumpToPractice(i) {
  const firstChapterFields = ['handle','status','accountsCenterReview','archive','name','startDate'];
  const selector = i < 6 ? '[data-field="' + firstChapterFields[i] + '"]' : '#lesson-practice';
  const target = document.querySelector(selector);
  if (!target) return;
  for (let parent = target.parentElement; parent; parent = parent.parentElement) {
    if (parent.tagName === 'DETAILS') parent.open = true;
  }
  target.focus({preventScroll:true});
  target.scrollIntoView({block:'center', behavior:'instant'});
}


function profile(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:KadrState.dateKey(d),label:d.toLocaleDateString('ru',{weekday:'short'}),date:d.getDate()}});app.innerHTML=`<section class="screen-heading"><h1>Мой профиль</h1><p>Имя, цель на день и сохранение прогресса между устройствами.</p></section><div class="profile-layout"><section class="settings-card cloud-card" id="cloudPanel" aria-label="Сохранение прогресса"></section><section class="settings-card"><div class="big-avatar">${icon('user')}</div><h2>${esc(state.fields.displayName||'Начинающий автор')}</h2><span class="level-pill">${rank()} · ${state.done.length*50} XP</span>${field('displayName','Как тебя называть?','Твоё имя')}<p class="note">Так имя будет выглядеть в твоём профиле практикума.</p></section><section class="settings-card"><h3>${icon('flag')} Цель на день</h3><p>Выбери посильный темп. Цель считается по впервые завершённым миссиям.</p><div class="goal-options">${[1,2,3].map(n=>`<button data-goal="${n}" aria-pressed="${state.goal===n}" class="${state.goal===n?'selected':''}"><b>${n}</b><span>${n===1?'миссия':'миссии'}</span><small>${n===1?'Спокойно':n===2?'Уверенно':'Интенсивно'}</small></button>`).join('')}</div><h3 class="activity-title">Последние 7 дней</h3><div class="activity-week">${days.map(d=>`<div><span>${d.label}</span><b class="${state.activity[d.key]?'day-done':''}">${state.activity[d.key]?'<svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12l4 4L19 6"/></svg>':d.date}</b></div>`).join('')}</div><p class="note">Отмечаем дни, когда ты завершал новые миссии. Старые отметки до обновления приложения не восстанавливаются.</p></section><section class="settings-card preferences"><div><h3>Звук награды</h3><p>Короткий сигнал при завершении новой миссии.</p></div><button role="switch" aria-checked="${!!state.sound}" id="soundToggle" class="toggle ${state.sound?'on':''}" aria-label="Звук награды"><span></span></button></section><section class="settings-card preferences"><div><h3>Твои данные</h3><p>Текстовую карточку можно перечитать офлайн. Полная копия для восстановления хранится в разделе «Рюкзак».</p></div><button class="secondary" id="download">Скачать карточку ${icon('bag')}</button></section></div>`}
function playReward(){if(!state.sound)return;try{const A=window.AudioContext||window.webkitAudioContext;const ctx=new A();[523,659,784].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;g.gain.setValueAtTime(0,ctx.currentTime+i*.12);g.gain.linearRampToValueAtTime(.05,ctx.currentTime+i*.12+.02);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.12+.22);o.start(ctx.currentTime+i*.12);o.stop(ctx.currentTime+i*.12+.23)});setTimeout(()=>ctx.close(),800)}catch{}}
const shots=[['type','Тип аккаунта','Сверь выбранный тип с моими настройками.'],['tags','Метки и упоминания','Проверь, кто может упоминать тебя.'],['reuse','Репосты и использование','Разрешения на распространение контента.'],['followers','Подписки и приглашения','Сверь настройки обработки подписок.'],['permissions','Разрешения телефона','На моём телефоне: доступ к фото разрешён.'],['quality','Качество медиа','У меня включена загрузка в самом высоком качестве.']];
function lesson(i){if(i>=6){courseLesson(i);return}current=i;state.last=i;persist();let body='',intro='',result='';
if(i===0){intro='Я начинаю не с нового профиля, а с выбора аккаунта, который готов вести регулярно. Возможно, подходящий уже есть у тебя.';result='Ник аккаунта и понятная точка входа.';body=block('Твоя задача',`<p>Рассмотри свой личный профиль или старый неиспользуемый аккаунт. Убедись, что можешь войти и восстановить доступ при необходимости.</p>${field('handle','Ник аккаунта','@my_account')}${select('accountKind','С чего начинаешь?',['Личный аккаунт','Старый неиспользуемый аккаунт','Уже публикую, меняю подход','Есть только новый аккаунт'])}${check('access','Я могу войти и имею доступ к восстановлению аккаунта')}`)+block('Защищаю доступ',`<p>Перед стартом я проверяю, что не потеряю аккаунт посреди работы. Путь: профиль → меню справа вверху → «Центр аккаунтов» → «Пароль и безопасность».</p>${check('secContacts','В Центре аккаунтов указаны мои актуальные почта и телефон, и у меня есть к ним доступ')}${check('sec2fa','Включена двухфакторная аутентификация: «Пароль и безопасность» → «Двухфакторная аутентификация»')}${check('secCodes','Резервные коды сохранены не только в этом телефоне')}${check('secPassword','Пароль уникальный и не совпадает с паролем от почты')}<p class="note">Эти отметки не обязательны для завершения шага, но я прохожу их до первых публикаций. <a href="https://help.instagram.com/iphone-app/566810106808145" target="_blank" rel="noopener">Instagram: двухфакторная аутентификация</a></p>`)+detail('Какой способ защиты я выбираю','Instagram предлагает приложение-аутентификатор, SMS или WhatsApp. Я выбираю способ, к которому точно сохраню доступ при смене телефона. Резервные коды нужны, если код не приходит: храню их отдельно от телефона - в менеджере паролей или на бумаге.')+detail('Мне пишут, что аккаунт заблокируют','Я не отправляю пароль и коды в ответ на сообщения и не перехожу по ссылкам из подозрительных писем. Предупреждения проверяю только внутри приложения: в разделе «Статус аккаунта» на следующем шаге.')+detail('Зачем начинать с существующего аккаунта?','В моей практике существующие аккаунты часто запускались лучше новых. Это наблюдение, а не гарантия охватов. Старый профиль тоже может иметь ограничения или неподходящую аудиторию - дальше проверим его состояние. Если есть только новый аккаунт, продолжать обучение можно.')+detail('Мне неловко публиковать для знакомых','Выбери профиль, которым готов регулярно пользоваться. На старте достаточно определить, какие темы и кадры комфортно показывать публично. Не нужно сразу раскрывать всю личную жизнь.')}
if(i===1){intro='Перед стартом я всегда читаю сообщения самой платформы. Так я фиксирую состояние, с которого начинаю.';result='Проверенный статус и список вопросов, если они есть.';body=block('Проверь статус',`<ol><li>Открой меню профиля и раздел настроек.</li><li>Найди «Статус аккаунта».</li><li>Открой каждый доступный пункт и прочитай сообщения.</li></ol>${screenGuide('status','Статус аккаунта',1)}${select('status','Что показано у тебя?',['Ограничений не обнаружено','Есть предупреждение','Не могу найти раздел'])}${area('statusNote','Заметка о состоянии аккаунта','Что стоит проверить или исправить?')}`)+detail('Зачем это нужно?','Низкие просмотры сами по себе не объясняют причину. Проверка статуса помогает увидеть сообщения платформы и зафиксировать исходное состояние. Зелёные отметки не гарантируют рост будущих роликов.')+detail('У меня предупреждение','Открой сообщение и прочитай причину. Изучи доступные действия исправления или обжалования. Не удаляй публикации наугад. Можно продолжать читать уроки, а в твоей карточке останется выбранный ответ «Есть предупреждение».')+detail('Не могу найти раздел','Названия и расположение пунктов могут отличаться. Поищи «Статус аккаунта» в настройках. Если раздел недоступен, сохрани эту отметку и вернись к проверке позже.')}
if(i===2){intro='Я прохожу настройки по своим реальным экранам - по одной группе за раз. Отмечай проверенное, и следующая группа откроется сама.';result='Проверенный Центр аккаунтов и шесть групп настроек.';body=settingsSteps()+detail('Почему нельзя просто включить всё?','Настройки выполняют разные задачи: качество загрузки, метки, распространение контента и доступ к телефону. Большее количество включённых функций само по себе не означает готовность к продвижению.')+detail('Зачем загрузка в высоком качестве?','На моём экране включена загрузка в самом высоком качестве. Она не исправляет размытую съёмку и неудачный исходник. Качество ролика начинается до публикации.')+detail('Зачем я разрешил камеру и микрофон?','На моём актуальном скриншоте оба разрешения включены: камера нужна для съёмки внутри приложения, микрофон - для записи звука. Доступ ко всем фото позволяет выбирать готовые исходники. Контакты, геолокация и уведомления у меня запрещены - это отдельные разрешения с другими задачами.')+detail('У меня другой экран','Сверь название функции. Если нужного пункта нет, выбери «Пункт недоступен». Если назначение непонятно, выбери «Нужно разобраться», не меняя похожие настройки наугад.')}
if(i===3){intro='Новый этап не требует стирать историю. Я решаю, какие публикации оставить в профиле, а какие постепенно убрать в архив.';result='Выбранный способ работы со старым контентом.';body=block('Выбери свой вариант',`${select('archive','Старые публикации',['Оставляю как есть','Часть буду архивировать','Старых публикаций нет'])}<p>Чтобы изменить вид профиля, я использую <b>архивирование по 1–2 публикации в день</b> параллельно с началом новых публикаций.</p><p class="note">Выбираем именно «Архивировать», не «Удалить». Темп - моя рекомендация.</p>${area('archiveNote','Что хочешь оставить или убрать?','Например: оставить личные фото, архивировать старую рекламу')}`)+detail('Почему именно архивирование?','Я выбираю архивирование и не рекомендую массово удалять старые публикации ради нового старта. В своей практике я отношусь к массовому удалению как к лишнему риску для стабильной работы аккаунта и охватов. При этом подтверждённого правила Instagram «удаление публикаций снижает охваты или обязательно вызывает ограничения» у меня нет. Поэтому мой порядок работы - постепенно архивировать по 1-2 публикации в день, сохраняя возможность вернуть материалы. Это моя осторожная рекомендация, а не установленный платформой лимит. Перед подтверждением проверь, что выбрано именно архивирование.')+detail('Нужно сначала полностью очистить профиль?','Нет. В этом методе новые публикации и постепенное архивирование идут параллельно. Не откладывай обучение до идеального оформления.')}
if(i===4){intro='Человек посмотрел ролик и открыл профиль. Я хочу, чтобы за пару секунд он понял, что найдёт здесь дальше.';result='Имя, описание и понятное направление блога.';body=block('Собери основу',`${field('name','Имя в профиле','Например: Анна · истории о семье')}${select('format','Формат',['С лицом','Без лица','Оба формата'])}${area('topics','О чём будет блог?','Например: отношения, семья и жизненные решения')}${field('tone','Как звучит твоя подача?','Спокойно и прямо, без нравоучений')}<p class="note">Поле «Имя» отображается в профиле. Ник с @ ты указал в первом шаге: это отдельное поле. В имени можно коротко обозначить тему блога.</p><p><b>Аватарка:</b> узнаваемый портрет или простой знак для блога без лица. Проверь, различим ли он в маленьком круге.</p>${check('avatar','Я выбрал читаемую аватарку')}`)+block('Напиши описание',`<p>Тема → особенность подачи → приглашение остаться.</p><p class="note">Пример: «Об отношениях, семье и непростых решениях. Истории, в которых узнаёшь себя. Оставайся, если любишь смотреть глубже».</p>${area('bio','Мой вариант описания','Текст для своего профиля')}<small id="count" aria-live="polite" style="color:${Array.from(state.fields.bio||'').length>150?'#b83d26':'#6d7066'}">${Array.from(state.fields.bio||'').length} / 150 символов</small><div class="actions"><button class="secondary" id="copyPrompt">Скопировать промпт <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></button><button class="secondary" id="copyBio">Скопировать описание</button></div>${check('profileUpdated','Я перенёс имя, аватарку и описание в профиль')}`)+detail('Если у меня пока нет ниши?','Выбери несколько связанных тем, которые действительно интересны. Это предварительное направление: позже уточнишь его по результатам. Сейчас описание должно честно объяснять, какой контент будет в блоге.')+detail('Что писать, если я не эксперт?','Говори о том, что публикуешь: наблюдения, личный опыт, истории или подборки. Не приписывай себе квалификацию и не обещай решать чужие проблемы без оснований.')+detail('Проверь описание на конкретность','Назови три будущих ролика, которые подходят под описание. Если это сложно, уточни формулировку. После ответа ИИ самостоятельно проверь текст и его длину.')}
if(i===5){intro='Я сохраняю исходные данные. Через несколько недель сравниваю результат с собой, а не с чужой удачной публикацией.';result='Твоя карточка аккаунта готова.';body=block('Точка отсчёта',`${field('startDate','Дата начала','','date')}${field('followers','Подписчиков сейчас','0','number')}${field('startAvgViews','Средние просмотры последних Reels','Например: 350','number')}${field('startReach','Охваченные аккаунты за 30 дней','Если статистика доступна','number')}${select('trial','Пробный режим',['Есть','Нет','Пока не знаю'])}${area('startNote','Что хочешь отметить на старте?','Ожидания, трудности, особенности аккаунта')}`)+detail('Где я беру эти цифры','Средние просмотры считаю по последним 3–5 роликам: открываю каждый, записываю просмотры и делю сумму на количество роликов. Охват беру в профессиональной панели → «Статистика» за последние 30 дней. Если аккаунт только что стал профессиональным или роликов ещё нет, оставляю поле пустым: статистика появляется только по публикациям после переключения. В седьмой главе я сравниваю результаты именно с этими числами.')+detail('Почему записываем даже маленькие цифры?','Точка старта нужна для сравнения с собой. Чужая удачная публикация не показывает весь путь автора. Свои записи помогут замечать изменения и выбирать следующие действия.')+block('Финальная сверка',`${check('finalCheck','Я проверил свои ответы и сохранил исходные показатели')}<p>Ответы сохраняются по мере заполнения. Карточка доступна в «Рюкзаке» на любом этапе.</p><p class="note">Данные хранятся в этом браузере на этом устройстве. В «Рюкзаке» можно скачать ответы для чтения или резервную копию JSON для восстановления прогресса.</p>`)}
body=firstModuleVisual(i)+body;if(i===5)body+=moduleOneReview();
app.innerHTML=`<article class="lesson">${lessonHeader(i,intro)}<div class="lesson-layout"><div class="lesson-body">${body}<div class="lesson-end"><button class="primary" id="complete">${state.done.includes(i)?'Сохранить и продолжить':'Завершить шаг'} <span><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></span></button>${i>0?`<button class="text-button" data-lesson="${i-1}">Предыдущий шаг</button>`:''}</div><p class="note">Самостоятельная практика. Отметь шаг, когда проверишь свой результат.</p></div><aside class="side-note"><span class="eyebrow">Результат миссии</span><p>${result}</p></aside></div></article>`}

function baseMaterialText(){return `МОЯ ТОЧКА СТАРТА\n\nАккаунт: ${state.fields.handle||'Не указан'}\nИмя: ${state.fields.name||'—'}\nТемы: ${state.fields.topics||'—'}\nФормат: ${state.fields.format||'—'}\nОписание: ${state.fields.bio||'—'}\nСтатус: ${state.fields.status||'—'}\nЗаметка: ${state.fields.statusNote||'—'}\nСтарые публикации: ${state.fields.archive||'—'}\nДата старта: ${state.fields.startDate||'—'}\nПодписчиков: ${state.fields.followers??'—'}\nСредние просмотры на старте: ${state.fields.startAvgViews||'—'}\nОхват за 30 дней на старте: ${state.fields.startReach||'—'}\nПробный режим: ${state.fields.trial||'—'}\nМиссий пройдено: ${state.done.length}/42\n\nПодача: ${state.fields.tone||'—'}\nПлан архивации: ${state.fields.archiveNote||'—'}\nЗаметки на старте: ${state.fields.startNote||'—'}\nТип выбранного аккаунта: ${state.fields.accountKind||'Не указан'}\nЦентр аккаунтов: ${state.fields.accountsCenterReview||'Не проверено'}\nТип и видимость: ${state.fields.accountSetup||'Не отмечено'}\nЗащита доступа: ${[['secContacts','контакты'],['sec2fa','2FA'],['secCodes','резервные коды'],['secPassword','пароль']].filter(([k])=>state.fields[k]).map(([,t])=>t).join(', ')||'не отмечено'}\n\nНастройки:\n${shots.map(([k,t])=>t+': '+(state.fields['setting_'+k]||'Не проверено')).join('\n')}`}
function render(v,mode='push'){v=KadrState.route(KadrState.hash(v));const target=KadrState.hash(v);if(mode==='replace')history.replaceState(null,'',target);else if(mode==='push'&&location.hash!==target)history.pushState(null,'',target);current=v;navRender();document.body.classList.toggle('in-lesson',typeof v==='number');document.querySelector('#crumb').textContent=typeof v==='number'?'Миссия '+(v%6+1)+' / '+chapters[Math.floor(v/6)].title:({home:'Карта обучения',materials:'Мой рюкзак',achievements:'Мои награды',profile:'Мой профиль',calendar:'Календарь практики',help:'Центр помощи',preflight:'Проверка перед публикацией'}[v]||'Карта обучения');if(typeof v==='number')lesson(v);else if(v==='materials')materials();else if(v==='achievements')achievements();else if(v==='profile')profile();else if(v==='calendar')calendar();else if(v==='help')helpCenter();else if(v==='preflight')preflight();else if(String(v).startsWith('chapter/'))courseHome(Number(v.split('/')[1])-1);else courseHome(Math.floor(state.last/6));if(typeof v==='number')lessonExtras(v);document.title=(typeof v==='number'?missions[v][0]:document.querySelector('#crumb').textContent)+' · Кадр';window.KadrCloud?.paint();app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function invalidField(i){
 if(i>=18&&i<42){const issue=workshopIssue(i);if(issue)return issue;return state.fields['check_'+i]?null:['check_'+i,'Подтверди выполнение задания.'];}
 if(i>=12&&i<=17)return state.fields["check_"+i]?null:["check_"+i,"Подтверди выполнение задания."];
 if(i===11){const miss=chapterTwoChecks.find(([k])=>!state.fields[k]);if(miss)return miss}
 if(i>=6&&i<42){if(!optionalAnswer(i)&&!String(state.fields['answer_'+i]||'').trim())return ['answer_'+i,'Запиши результат практики.'];if(!state.fields['check_'+i])return ['check_'+i,'Подтверди выполнение задания.'];return null;}
 const f=state.fields, text=k=>typeof f[k]==='string'&&f[k].trim();
 const need=(k,message)=>[k,message];
 if(i===0){if(!text('handle'))return need('handle','Укажи ник аккаунта.');if(!f.accountKind)return need('accountKind','Выбери, с какого аккаунта начинаешь.');if(!f.access)return need('access','Подтверди, что можешь войти в аккаунт.');}
 if(i===1&&!f.status)return need('status','Выбери результат проверки статуса.');
 if(i===2){if(!f.accountsCenterReview)return need('accountsCenterReview','Отметь результат проверки Центра аккаунтов.');const missing=shots.find(([k])=>!f['setting_'+k]);if(missing)return need('setting_'+missing[0],'Отметь результат проверки: '+missing[1]+'.');}
 if(i===3&&!f.archive)return need('archive','Выбери, что делать со старыми публикациями.');
 if(i===4){for(const [k,msg] of [['name','Укажи имя или название блога.'],['format','Выбери формат блога.'],['topics','Запиши темы будущего блога.'],['bio','Напиши описание профиля.']])if(!text(k))return need(k,msg);if(Array.from(f.bio).length>150)return need('bio','Сократи описание до 150 символов. Сейчас '+Array.from(f.bio).length+'.');if(!f.avatar)return need('avatar','Отметь выбор аватарки.');if(!f.profileUpdated)return need('profileUpdated','Подтверди, что перенёс оформление в профиль.');}
 if(i===5){if(!KadrState.validDate(f.startDate))return need('startDate','Укажи дату начала.');if(f.followers===undefined||String(f.followers).trim()===''||!Number.isSafeInteger(Number(f.followers))||Number(f.followers)<0)return need('followers','Укажи целое число подписчиков: 0 или больше.');if(!f.trial)return need('trial','Выбери, доступен ли пробный режим.');if(!f.finalCheck)return need('finalCheck','Подтверди проверку исходных показателей.');}
 return null;
}
function valid(i){return Number.isInteger(i)&&i>=0&&i<42&&!invalidField(i)}
function showFieldError(issue){document.querySelectorAll('[aria-invalid]').forEach(e=>{e.removeAttribute('aria-invalid');e.removeAttribute('aria-describedby')});document.querySelector('#fieldError')?.remove();const [key,message]=issue;const input=document.querySelector('[data-field="'+key+'"]');if(input){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','fieldError');const err=document.createElement('p');err.id='fieldError';err.className='field-error';err.setAttribute('role','alert');err.textContent=message;input.closest('label').after(err);const box=input.closest('details');if(box)box.open=true;input.focus();input.scrollIntoView({block:'center',behavior:'instant'});}toast(message)}
async function completeMission(){
 if(typeof current!=='number')return;
 const mission=current,issue=invalidField(mission);if(issue){showFieldError(issue);return}
 const button=document.querySelector('#complete');if(button.disabled)return;button.disabled=true;
 const finish=()=>{persist();const fresh=!state.done.includes(mission);if(fresh){const day=dayKey();state.done.push(mission);state.completedOn[mission]=day;state.activity[day]=(state.activity[day]||0)+1;}const stored=persist();render(mission,'none');showReward(mission,fresh);if(!stored)toast('Миссия отмечена только на время сеанса. Скачай карточку.');};
 try{if(navigator.locks)await navigator.locks.request('kadr-progress',finish);else finish()}finally{if(button.isConnected)button.disabled=false}
}
function openDialog(id){const d=document.querySelector('#'+id);if(!d.open)d.showModal();const h=d.querySelector('h2');if(h){h.id='dialogTitle';h.tabIndex=-1;d.setAttribute('aria-labelledby','dialogTitle');h.focus({preventScroll:true})}}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Скопировано')}catch{toast('Копирование недоступно. Выдели текст вручную.')}}
document.addEventListener('input',e=>{if(!e.target.dataset.field)return;state.fields[e.target.dataset.field]=e.target.type==='checkbox'?e.target.checked:e.target.value;persist();document.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.removeAttribute('aria-describedby')});document.querySelector('#fieldError')?.remove();if(e.target.dataset.field==='displayName'){document.querySelector('.settings-card h2').textContent=String(state.fields.displayName||'').trim()||'Начинающий автор';}if(e.target.dataset.field==='bio'){let n=Array.from(e.target.value).length;document.querySelector('#count').textContent=n+' / 150 символов';document.querySelector('#count').style.color=n>150?'#b83d26':'#6d7066'}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-image]');if(!el)return;if(el.id==='moreNav')showMobileNav();if(el.hasAttribute('data-jump-practice'))jumpToPractice(current);if(el.dataset.view){if(el.closest('.more-menu'))document.querySelector('#reward').close();render(el.dataset.view);}if(el.dataset.lesson!==undefined)render(Number(el.dataset.lesson));if(el.id==='chapters')showChapters();if(el.dataset.mode){const top=window.scrollY;state.mapMode=el.dataset.mode;persist();courseHome(String(current).startsWith('chapter/')?Number(current.split('/')[1])-1:Math.floor(state.last/6));document.querySelector('[data-mode="'+state.mapMode+'"]').focus({preventScroll:true});window.scrollTo({top,behavior:'instant'})}if(el.dataset.goal){state.goal=Number(el.dataset.goal);persist();profile();navRender();window.KadrCloud?.paint();toast('Цель обновлена')}if(el.id==='soundToggle'){state.sound=!state.sound;persist();profile();window.KadrCloud?.paint();if(state.sound)playReward()}if(el.id==='closeReward')document.querySelector('#reward').close();if(el.id==='rewardMap'){document.querySelector('#reward').close();render('home')}if(el.id==='rewardContinue'){document.querySelector('#reward').close();render(el.dataset.next==='home'?'home':Number(el.dataset.next))}if(el.id==='complete')await completeMission();if(el.id==='copyPrompt')copy(prompt());if(el.id==='copyBio'){if(String(state.fields.bio||'').trim())copy(state.fields.bio);else toast('Сначала напиши описание профиля.');}if(el.id==='download'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([materialText()],{type:'text/plain;charset=utf-8'}));a.download='my-account.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}if(el.dataset.image){const d=document.querySelector('#lightbox');d.classList.remove('zoomed');d.querySelector('img').src=el.dataset.image;d.querySelector('img').alt=el.querySelector('img')?.alt||'Скриншот настройки';document.querySelector('#zoomImage').textContent='Увеличить';document.querySelector('#zoomImage').setAttribute('aria-pressed','false');openDialog('lightbox')}if(el.id==='zoomImage'){const z=document.querySelector('#lightbox').classList.toggle('zoomed');el.textContent=z?'Показать целиком':'Увеличить';el.setAttribute('aria-pressed',String(z));}if(el.id==='closeImage')document.querySelector('#lightbox').close()});document.querySelector('.brand').onclick=e=>{e.preventDefault();render('home')};window.addEventListener('popstate',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());render(KadrState.route(location.hash),'none')});/* booted by course.js */if(storageUnavailable)toast('Сохранённые данные недоступны. Приложение открыто без них.');

window.addEventListener('storage',e=>{if(e.key!==progressKey||!e.newValue)return;try{const previousEpoch=state.epoch;state=KadrState.merge(saved,state,JSON.parse(e.newValue));saved=structuredClone(state);navRender();if(previousEpoch!==state.epoch){document.querySelectorAll('dialog[open]').forEach(d=>d.close());render(current,'none');toast('В другой вкладке восстановлена резервная копия. Данные обновлены.')}else if(typeof current!=='number'&&current!=='profile'&&current!=='preflight'&&current!=='help'&&current!=='calendar')render(current,'none');}catch{}});

window.addEventListener('hashchange',()=>{if(location.hash!=='#app'&&KadrState.route(location.hash)!==current)render(KadrState.route(location.hash),'none')});

function moduleOneReview(){const pending=[];if(state.fields.status!=='Ограничений не обнаружено')pending.push(['Статус аккаунта: '+(state.fields.status||'не проверен'),1]);if(state.fields.accountsCenterReview!=='Один Instagram, проверено')pending.push(['Центр аккаунтов: '+(state.fields.accountsCenterReview||'не проверен'),2]);for(const [k,t] of shots)if(state.fields['setting_'+k]!=='Проверено')pending.push([t+': '+(state.fields['setting_'+k]||'не проверено'),2]);return block('Сверяю первый модуль',`<p>Завершённые шаги: ${state.done.filter(n=>n<6).length} из 6. Можно возвращаться к любому заданию и уточнять ответы.</p><div class="module-review">${missions.slice(0,5).map((m,i)=>`<button class="secondary" data-lesson="${i}">${icon(state.done.includes(i)?'check':'chevron')}${m[0]} · ${state.done.includes(i)?'завершено':'не завершено'}</button>`).join('')}</div>${pending.length?`<h4>К чему нужно вернуться</h4><p class="note">Эти отметки не мешают читать дальше. Завершение урока не снимает ограничения в Instagram.</p><ul>${pending.map(([t,i])=>`<li><button class="text-button review-link" data-lesson="${i}">${esc(t)}</button></li>`).join('')}</ul>`:'<p>Статус и все группы настроек проверены. При изменениях в аккаунте обнови ответы.</p>'}`)}
